        "isDefaultEntryPoint": True
      }
    },
    {
      "id": "extractReceiptFields",
      "type": IXP_TYPE,
      "typeVersion": IXP_TYPE_VER,
      "display": {"label": "Extract Receipt Fields"},
      "inputs": {
        "model": model_blob,
        "modelName": ixp_node_def['inputDefaults']['modelName'],
        "description": "",
        "projectName": ixp_node_def['inputDefaults']['projectName'],
        "versionTag": "",
        "folderKey": ixp_node_def['inputDefaults']['folderKey'],
        "folderName": ixp_node_def['inputDefaults']['folderName'],
        "fileRef": "=js:$vars.start.output.receiptImage",
        "pageRange": ""
      },
      "outputs": {
        "output": {
          "name": "output",
          "type": "object",
          "source": "=this",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the node fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "parseFields",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {"label": "Parse merchant, date and total"},
      "inputs": {
        "script": """const fields = $vars.extractReceiptFields.output.ExtractionResult.ResultsDocument.Fields || [];
const get = name => (fields.find(f => f.FieldName === name) || {}).Values?.[0] ?? null;
return {
  merchant: get('vendor_name'),
  date: get('purchase_date'),
  total: get('total_amount')
};"""
      },
      "outputs": {
        "output": {
          "name": "output",
          "type": "object",
          "source": "=this",
          "var": "output"
        }
      }
    },
    {
      "id": "done",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {"label": "Done"},
      "inputs": {},
      "outputs": {
        "merchant": {
          "name": "merchant",
          "type": "string",
          "source": "=js:$vars.parseFields.output.merchant",
          "var": "merchant"
        },
        "date": {
          "name": "date",
